"""The tp4/next-1 window packs (scripts/ci/references/fusion-jobs/S5, generated by make_s5_jobs.py).

ORDER.txt (window 1), ORDER-W2.txt (window 2) and ORDER-SHIP.txt (after the owner's approval) list the folder's templates, each on the one image, with totals that match their headers; every NEEDS line
names earlier jobs; every smoke job carries the two Swift checkpoint keys, every prefix, replay and build job none (the job reader refuses the keys beside those steps); the pairs differ by the profile
alone; every template parses through the job reader with rc 0 (the ship build excepted: refused while the waiver is PENDING, by design); the pack is what the generator makes; nothing in it names a
host, an address or a registry."""

import json
from pathlib import Path
import re
import subprocess
import sys
import unittest

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import agent_turns  # noqa: E402
import c2_serving_job as job  # noqa: E402
import make_s5_jobs as pack  # noqa: E402
import serving_c2_contract as contract  # noqa: E402

PACK = pack.FOLDER
READER = HERE / 'c2_serving_job.py'
PROFILES = HERE / 'qwen_c2_profiles.json'
CATALOG = json.loads((HERE / 'qwen_c2_checkpoints.json').read_text(encoding='utf-8'))
SWIFT = CATALOG['checkpoints'][0]
AGENT = [pack.AGENT_TURNS_TEST] if pack.AGENT_TURNS_TEST else []

# job -> (serves Swift, profile, smoke tests, prefix plan)
EXPECTED = {
    'B0-build-window': (False, '', '', ''),
    'X0-status-rescan-reset': (False, '', '', ''),
    'A1-s5-audited-attach': (True, pack.AUDIT, ','.join(pack.A1_TESTS.split(',') + AGENT), ''),
    'A1N-s5-audited-attach-nowc': (True, pack.AUDIT_NOWC, ','.join(pack.A1_TESTS.split(',') + AGENT), ''),
    'A2-s5-prefix-exact-resume': (False, '', '', 'exact-resume'),
    'T1A-s4-control': (True, pack.SHIP4, ','.join(pack.TIMED_TESTS.split(',') + AGENT), ''),
    'T1B-s5-candidate': (True, pack.SHIP5, ','.join(pack.TIMED_TESTS.split(',') + AGENT), ''),
    'N1-long-answer-solo': (True, pack.SHIP5, pack.NP9_SOLO_TESTS, ''),
    'N2-long-answer8-short': (True, pack.SHIP5, pack.NP9_SHORT_TESTS, ''),
    'N3-long-answer8-deep': (True, pack.SHIP5, pack.NP9_DEEP_TESTS, ''),
    'A3-s5-tier-slice-audited': (False, '', '', 'tier-concurrent-sliced'),
    'B1-ship-build': (False, '', '', ''),
    'SR-platform-replay': (False, '', '', ''),
    'Z-reset': (False, '', '', ''),
}
# the templates each ORDER file lists, in order
WINDOWS = {
    'ORDER.txt': ['B0-build-window', 'X0-status-rescan-reset', 'A1-s5-audited-attach', 'T1A-s4-control', 'T1B-s5-candidate', 'Z-reset'],
    'ORDER-W2.txt': ['X0-status-rescan-reset', 'A2-s5-prefix-exact-resume', 'N1-long-answer-solo', 'N2-long-answer8-short', 'N3-long-answer8-deep', 'A3-s5-tier-slice-audited', 'Z-reset'],
    'ORDER-SHIP.txt': ['B1-ship-build', 'SR-platform-replay'],
}
NOT_IN_AN_ORDER = {'A1N-s5-audited-attach-nowc'}      # the fallback of A1, pushed by hand when A1 stopped on W3 WC alone


def order_lines(name):
    return [line.split() for line in (PACK / name).read_text(encoding='utf-8').splitlines() if line.strip() and not line.startswith('#')]


def directives(name, prefix):
    return [line[len(prefix):].split() for line in (PACK / name).read_text(encoding='utf-8').splitlines() if line.startswith(prefix)]


def values(name):
    return job.parse_env((PACK / (name + '.env')).read_text(encoding='utf-8'))


def run_reader(path):
    result = subprocess.run([sys.executable, '-B', '-s', str(READER), str(path), str(PROFILES)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
    return result.returncode, (result.stdout + result.stderr).decode('utf-8', 'replace')


class OrderTests(unittest.TestCase):
    def test_the_orders_list_exactly_the_folders_templates_on_one_image(self):
        self.assertEqual(sorted(path.stem for path in PACK.glob('*.env')), sorted(EXPECTED))
        self.assertEqual(sorted(path.name for path in PACK.glob('*.txt')), sorted(WINDOWS))
        listed = set()
        for name, jobs in WINDOWS.items():
            rows = order_lines(name)
            self.assertEqual([row[0] for row in rows], jobs, name)
            self.assertEqual({row[2] for row in rows}, {pack.IMAGE}, name)
            listed |= set(jobs)
        self.assertEqual(listed | NOT_IN_AN_ORDER, set(EXPECTED))
        self.assertEqual(pack.IMAGE, 'tp4-next-1', 'the placeholder tag of the brief')
        for name in EXPECTED:
            self.assertEqual(values(name)['C2_IMAGE_TAG'], pack.IMAGE)

    def test_the_modes_and_the_stop_rules(self):
        modes = {row[0]: row[1] for name in WINDOWS for row in order_lines(name)}
        self.assertEqual({key: modes[key] for key in ('B0-build-window', 'X0-status-rescan-reset', 'A1-s5-audited-attach', 'N1-long-answer-solo')}, {key: 'stop' for key in (
            'B0-build-window', 'X0-status-rescan-reset', 'A1-s5-audited-attach', 'N1-long-answer-solo')})
        self.assertEqual(modes['A3-s5-tier-slice-audited'], 'opt', 'the optional job the driver admits only if it fits')
        for key in ('T1A-s4-control', 'T1B-s5-candidate', 'A2-s5-prefix-exact-resume', 'Z-reset', 'B1-ship-build', 'SR-platform-replay'):
            self.assertEqual(modes[key], 'soft', key)
        self.assertEqual(order_lines('ORDER-W2.txt')[-1][0], 'Z-reset', 'the end sequence is last')
        self.assertEqual(order_lines('ORDER.txt')[-1][0], 'Z-reset')

    def test_the_header_totals_match_the_minutes(self):
        for name in WINDOWS:
            text = (PACK / name).read_text(encoding='utf-8')
            minutes = sum(int(row[3]) for row in order_lines(name))
            self.assertIn('%d minutes (%d h %d min) in all' % (minutes, minutes // 60, minutes % 60), text, name)
            for row in order_lines(name):
                self.assertIn('%s %s' % (row[0].split('-')[0], row[3]), text, name)

    def test_window_1_is_near_three_hours_of_cards_and_says_what_was_trimmed(self):
        rows = order_lines('ORDER.txt')
        cards = sum(int(row[3]) for row in rows if row[0] != 'B0-build-window')
        self.assertLessEqual(cards, 225, 'window 1 stays close to the 3 h target (the boots dominate)')
        self.assertGreaterEqual(cards, 150)
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        self.assertIn('WHAT WAS TRIMMED', text)
        self.assertIn('A2', text)
        self.assertIn('%d minutes of cards' % cards, text)

    def test_the_agent_turn_test_is_in_the_audited_attach_and_both_timed_legs_and_nowhere_else(self):
        self.assertEqual(pack.AGENT_TURNS_TEST, 'agent_turns')
        self.assertIn(pack.AGENT_TURNS_TEST, agent_turns.TESTS)
        for name, (_swift, _profile, tests, _plan) in EXPECTED.items():
            named = 'agent_turns' in tests.split(',')
            self.assertEqual(named, name in ('A1-s5-audited-attach', 'A1N-s5-audited-attach-nowc', 'T1A-s4-control', 'T1B-s5-candidate'), name)
            if named:
                self.assertEqual(values(name)['C2_SMOKE_TESTS'].split(',')[-1], 'agent_turns')
        base = {'A1-s5-audited-attach': 90, 'T1A-s4-control': 30, 'T1B-s5-candidate': 30}
        minutes = {row[0]: int(row[3]) for row in order_lines('ORDER.txt')}
        for name, plain in base.items():
            self.assertEqual(minutes[name], plain + pack.AGENT_TURNS_MINUTES[name.split('-')[0]], name)
        self.assertGreaterEqual(int(values('T1A-s4-control')['C2_BOX_MINUTES']) - 80, 15, 'a box for the extra ~15 minutes a leg')
        self.assertGreaterEqual(int(values('T1B-s5-candidate')['C2_BOX_MINUTES']) - 80, 15)

    def test_needs_lines_name_earlier_jobs_only(self):
        for name in WINDOWS:
            names = [row[0].split('-')[0] for row in order_lines(name)]
            for left_right in directives(name, '# NEEDS '):
                arrow = left_right.index('<-')
                left, right = left_right[:arrow], left_right[arrow + 1:]
                for token in left + right:
                    self.assertIn(token, names, (name, token))
                for later in left:
                    for earlier in right:
                        self.assertLess(names.index(earlier), names.index(later), (name, left_right))
        self.assertEqual(directives('ORDER.txt', '# NEEDS '), [['X0', '<-', 'B0'], ['A1', '<-', 'X0'], ['T1A', '<-', 'A1'], ['T1B', '<-', 'T1A']])
        self.assertEqual(directives('ORDER-SHIP.txt', '# NEEDS '), [['SR', '<-', 'B1']])

    def test_the_arc_range_covers_every_audited_boot_and_every_timed_job_and_nothing_else(self):
        names = [row[0].split('-')[0] for row in order_lines('ORDER.txt')]
        (first, last), = directives('ORDER.txt', '# ARC-ZERO ')
        self.assertEqual((first, last), ('A1', 'T1B'))
        for token in ('A1', 'T1A', 'T1B'):
            self.assertTrue(names.index(first) <= names.index(token) <= names.index(last), token)
        for token in ('B0', 'X0', 'Z'):
            self.assertFalse(names.index(first) <= names.index(token) <= names.index(last), token)
        names = [row[0].split('-')[0] for row in order_lines('ORDER-W2.txt')]
        (first, last), = directives('ORDER-W2.txt', '# ARC-ZERO ')
        self.assertEqual((first, last), ('A2', 'A3'))
        self.assertFalse(names.index(first) <= names.index('X0') <= names.index(last))

    def test_the_orders_say_what_is_new_never_push_a_tag_and_keep_the_run_rules(self):
        for name in WINDOWS:
            text = (PACK / name).read_text(encoding='utf-8')
            for phrase in ('never cancel a running card job', 'owner traffic waiver'):
                self.assertIn(phrase, text.lower() if phrase.islower() else text, (name, phrase))
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        for phrase in ('THE NEW DEVICE FACTS', 'FALLBACK', 'A1N', 'agent_turns', 'git mv'):
            self.assertIn(phrase, text + (PACK / 'ORDER-W2.txt').read_text(encoding='utf-8'), phrase)
        for name in EXPECTED:
            self.assertIn('no tag is pushed from the branch by its author', (PACK / (name + '.env')).read_text(encoding='utf-8'))

    def test_window_2_names_the_ceiling_and_how_to_take_it_out_of_window_1(self):
        text = (PACK / 'ORDER-W2.txt').read_text(encoding='utf-8')
        for phrase in ('"output_budget": 32768', 'WINDOW 1 AND THE CEILING', 'git mv ORDER-W2.txt ORDER.txt', 'docs/tp4-np9-answer32k.md'):
            self.assertIn(phrase, text)
        catalog = (HERE / 'qwen_c2_checkpoints.json').read_text(encoding='utf-8')
        self.assertEqual(catalog.count('"output_budget": 32768'), 1, 'the one line the order tells the operator to delete')


class TemplateTests(unittest.TestCase):
    def test_every_template_parses_with_rc_0_but_the_ship_build_which_is_refused_while_pending(self):
        for name in EXPECTED:
            with self.subTest(name=name):
                code, text = run_reader(PACK / (name + '.env'))
                if name == 'B1-ship-build':
                    self.assertEqual(code, 1, text)
                    self.assertIn('not APPROVED', text)
                else:
                    self.assertEqual(code, 0, text)

    def test_serving_jobs_carry_the_checkpoint_keys_and_the_expected_profile_and_tests(self):
        for name, (serves_swift, profile, tests, plan) in EXPECTED.items():
            with self.subTest(name=name):
                found = values(name)
                if serves_swift:
                    self.assertEqual((found['C2_MODEL_REPO'], found['C2_MODEL_REVISION']), (SWIFT['repo'], SWIFT['revision']))
                    self.assertEqual((pack.REPO, pack.REVISION), (SWIFT['repo'], SWIFT['revision']))
                else:
                    self.assertNotIn('C2_MODEL_REPO', found)
                    self.assertNotIn('C2_MODEL_REVISION', found)
                self.assertEqual(found.get('C2_PROFILE', ''), profile)
                self.assertEqual(found.get('C2_SMOKE_TESTS', ''), tests)
                self.assertEqual(found.get('C2_PREFIX_PLAN', ''), plan)

    def test_the_smoke_names_exist_in_the_harness(self):
        source = (HERE / 'c2_serving_smoke.py').read_text(encoding='utf-8')
        for name, (_swift, _profile, tests, _plan) in EXPECTED.items():
            for test in filter(None, tests.split(',')):
                self.assertTrue(re.search(r"'%s'" % re.escape(test), source) or test in ('warmup', 'coding', 'concurrent8_steady'), (name, test))

    def test_the_decode_pair_differs_by_the_profile_alone_and_the_control_is_the_approved_profile(self):
        keys = ('C2_SMOKE_TESTS', 'C2_BOX_MINUTES', 'C2_IMAGE_TAG', 'C2_MODEL_REPO', 'C2_MODEL_REVISION', 'C2_CARDS', 'C2_ACTIONS', 'C2_TELEMETRY')
        a, b = values('T1A-s4-control'), values('T1B-s5-candidate')
        self.assertEqual([a[key] for key in keys], [b[key] for key in keys])
        self.assertEqual((a['C2_PROFILE'], b['C2_PROFILE']), (pack.SHIP4, pack.SHIP5))
        self.assertEqual(a['C2_SMOKE_TESTS'].split(',')[:5], ['warmup', 'np1_live1', 'np1_live2', 'np1_live4', 'concurrent8_steady'])
        profiles = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles']
        self.assertFalse(job.bake_waiver_pending(profiles[pack.SHIP4]), 'the control is the APPROVED ship-4 profile')
        self.assertTrue(contract.traffic_waiver_pending(dict(profiles[pack.SHIP5], name=pack.SHIP5)) or profiles[pack.SHIP5]['owner_traffic_waiver']['decision'].startswith('APPROVED'))

    def test_the_audited_attach_runs_the_audit_twin_and_the_shapes_that_put_one_user_alone(self):
        found = values('A1-s5-audited-attach')
        self.assertEqual(found['C2_PROFILE'], pack.AUDIT)
        self.assertEqual(found['C2_SMOKE_TESTS'].split(',')[:6], ['warmup', 'coding', 'np1_live2', 'concurrent5_split', 'concurrent8_drain', 'concurrent8_steady'])
        self.assertGreater(int(found['C2_BOX_MINUTES']), int(order_lines('ORDER.txt')[2][3]), 'the box is longer than the estimate')
        self.assertLessEqual(int(found['C2_BOX_MINUTES']), 210)
        nowc = values('A1N-s5-audited-attach-nowc')
        self.assertEqual({key: value for key, value in nowc.items() if value != found.get(key)}, {'C2_PROFILE': pack.AUDIT_NOWC})

    def test_each_smoke_job_names_the_steady_test_and_a_box_inside_the_step(self):
        for name, (_swift, _profile, tests, _plan) in EXPECTED.items():
            found = values(name)
            if 'smoke' not in found['C2_ACTIONS'].split():
                continue
            with self.subTest(name=name):
                self.assertIn('concurrent8_steady', tests.split(','))
                self.assertTrue(0 < int(found['C2_BOX_MINUTES']) <= 210)
                self.assertEqual(found['C2_CARDS'], 'quad')
                self.assertEqual(found['C2_TELEMETRY'], '1')

    def test_no_checkpoint_job_uses_a_step_that_does_not_forward_the_checkpoint(self):
        for name in EXPECTED:
            actions = set(values(name)['C2_ACTIONS'].split())
            if values(name).get('C2_MODEL_REPO'):
                self.assertFalse(actions - set(job.MODEL_ACTIONS), name)
            if actions & {'prefix', 'replay', 'build'}:
                self.assertNotIn('C2_MODEL_REPO', values(name), name)

    def test_the_prefix_arms_run_the_audited_twin_on_the_plans_they_name(self):
        for name, plan in (('A2-s5-prefix-exact-resume', 'exact-resume'), ('A3-s5-tier-slice-audited', 'tier-concurrent-sliced')):
            found = values(name)
            self.assertEqual((found['C2_ACTIONS'], found['C2_PREFIX_PLAN'], found['C2_PREFIX_PROFILE'], found['C2_PREFIX_BASELINE']), ('reset prefix', plan, pack.AUDIT, 'none'), name)

    def test_the_build_bakes_the_approved_ship_profile_with_the_oneq_graft_and_the_ship_build_the_candidate(self):
        found = values('B0-build-window')
        self.assertEqual((found['C2_BAKE_DEFAULT_PROFILE'], found['C2_BAKE_GRAFT']), (pack.SHIP4, 'K64j-OQ'))
        profiles = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles']
        self.assertFalse(job.bake_waiver_pending(profiles[pack.SHIP4]), 'the ship-4 waiver is APPROVED: the window build is not refused')
        ship = values('B1-ship-build')
        self.assertEqual((ship['C2_BAKE_DEFAULT_PROFILE'], ship['C2_BAKE_GRAFT']), (pack.SHIP5, 'K64j-OQ'))
        self.assertEqual(job.bake_waiver_pending(profiles[pack.SHIP5]), profiles[pack.SHIP5]['owner_traffic_waiver']['decision'].startswith('PENDING'))
        for name in EXPECTED:
            if name not in ('B0-build-window', 'B1-ship-build'):
                self.assertNotIn('C2_BAKE_DEFAULT_PROFILE', values(name), name)

    def test_the_platform_replay_is_the_candidates_and_waits_for_its_approval(self):
        found = values('SR-platform-replay')
        self.assertEqual((found['C2_ACTIONS'], found['C2_REPLAY_PROFILE'], found['C2_PLATFORM_IMAGE']), ('reset replay', pack.SHIP5, 'local:thin-layer'))
        text = (PACK / 'SR-platform-replay.env').read_text(encoding='utf-8')
        self.assertIn('AFTER THE OWNER APPROVES', text)
        self.assertIn('BY THE IMAGE DEFAULT', text)

    def test_the_templates_name_the_lines_the_arms_log(self):
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'T1B-s5-candidate.env').read_text(encoding='utf-8'))
        for phrase in ('[NP1] kv scratch:', '[SOLO-PACKED] admitted min_users=1 scratch_pages=16500 (owner traffic waiver <id>)', 'packed padded block admitted min_users=1 users=4 max_idle=4', 'np1_report.py',
                       'octo_compare.py', 'octo_judge.py', 'agent_turns.py report', 'window carry engaged', 'host tier restore slice on blocks=512 ms=200'):
            self.assertIn(phrase, text)
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'A1-s5-audited-attach.env').read_text(encoding='utf-8'))
        for phrase in ('(gate only)', 'A1N', 'never been through a compiler', 'reason=8 users'):
            self.assertIn(phrase, text)


class GeneratedTests(unittest.TestCase):
    def test_the_checked_in_pack_is_what_the_generator_makes(self):
        self.assertEqual(pack.main(['--check']), 0)

    def test_with_the_agent_turn_test_taken_out_the_jobs_and_the_minutes_shrink(self):
        from unittest import mock

        with mock.patch.object(pack, 'AGENT_TURNS_TEST', ''):
            text = pack.generate()
        self.assertNotIn('agent_turns', text['T1B-s5-candidate.env'].split('C2_CARDS')[1])
        self.assertIn('A1-s5-audited-attach stop tp4-next-1 90', text['ORDER.txt'])
        self.assertIn('T1A-s4-control soft tp4-next-1 30', text['ORDER.txt'])

    def test_nothing_in_the_pack_names_a_host_an_address_or_a_registry(self):
        for path in PACK.glob('*'):
            text = path.read_text(encoding='utf-8')
            with self.subTest(path=path.name):
                self.assertEqual([needle for needle in ('/home/', 'zot.', 'ghcr', 'docker.io', '.local', '.internal', 'localhost') if needle in text], [])
                self.assertIsNone(re.search(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', text), 'an IP address')
                self.assertIsNone(re.search(r'blackhole-[0-9A-F]{16}', text), 'a card id')
                self.assertIsNone(re.search(r'\bsha256:[0-9a-f]{12,}', text), 'an image digest')
                self.assertNotIn('\r', text)


if __name__ == '__main__':
    unittest.main()
